import{_ as i,o as a,c as e,a0 as r}from"./chunks/framework.L_oL6aia.js";const h=JSON.parse('{"title":"Karing 客户端安装与使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/karing.md","filePath":"guide/karing.md"}'),s={name:"guide/karing.md"};function l(o,t,n,c,g,d){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="karing-客户端安装与使用教程" tabindex="-1">Karing 客户端安装与使用教程 <a class="header-anchor" href="#karing-客户端安装与使用教程" aria-label="Permalink to &quot;Karing 客户端安装与使用教程&quot;">​</a></h1><p>本教程将引导您安装并配置 Karing 客户端。Karing 是一款全平台通用的网络代理工具，各平台（Windows、Android、macOS、iOS）的界面与操作逻辑基本一致，本教程以 <strong>Windows 端</strong>为例进行演示。</p><h2 id="一、软件下载" tabindex="-1">一、软件下载 <a class="header-anchor" href="#一、软件下载" aria-label="Permalink to &quot;一、软件下载&quot;">​</a></h2><p>请根据您的设备系统，选择对应的安装包进行下载：</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作系统</th><th style="text-align:left;">适用设备/芯片</th><th style="text-align:left;">下载文件名</th></tr></thead><tbody><tr><td style="text-align:left;">Windows</td><td style="text-align:left;">64位通用</td><td style="text-align:left;"><code>karing_windows_x64.exe</code></td></tr><tr><td style="text-align:left;">Android</td><td style="text-align:left;">安卓手机/平板</td><td style="text-align:left;"><code>karing_android.apk</code></td></tr><tr><td style="text-align:left;">macOS</td><td style="text-align:left;">Intel 芯片</td><td style="text-align:left;"><code>karing_macos.dmg</code></td></tr><tr><td style="text-align:left;">macOS / iOS</td><td style="text-align:left;">Apple Silicon (M系列) / iPhone / iPad</td><td style="text-align:left;">登录美区 Apple ID，前往 App Store 搜索 <strong>Karing</strong> 下载</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 大陆用户下载提示</p><p>请直接访问官方网站高速下载通道：<a href="https://zip.suyungo.de/" target="_blank" rel="noreferrer">https://zip.suyungo.de/</a></p></div><h2 id="二、快速使用指南" tabindex="-1">二、快速使用指南 <a class="header-anchor" href="#二、快速使用指南" aria-label="Permalink to &quot;二、快速使用指南&quot;">​</a></h2><h3 id="step-1-基础初始化设置" tabindex="-1">Step 1. 基础初始化设置 <a class="header-anchor" href="#step-1-基础初始化设置" aria-label="Permalink to &quot;Step 1. 基础初始化设置&quot;">​</a></h3><p>下载完成后，双击打开 <code>karing_windows_x64.exe</code> 安装包。首次启动会触发新手引导，请按照以下步骤完成基础配置：</p><ol><li>在地区选择界面，选择 <strong>中国 (China)</strong></li><li>点击 <strong>下一步</strong></li><li>根据提示，开启 <strong>新手模式</strong></li></ol><img src="https://doc.mimy.cc/gykaring11.webp" width="600" alt="基础初始化设置 01"><img src="https://doc.mimy.cc/gykaring22.webp" width="600" alt="基础初始化设置 02"><img src="https://doc.mimy.cc/gykaring33.webp" width="600" alt="基础初始化设置 03"><img src="https://doc.mimy.cc/gykaring44.webp" width="600" alt="基础初始化设置 04"><img src="https://doc.mimy.cc/gykaring55.webp" width="600" alt="基础初始化设置 05"><img src="https://doc.mimy.cc/gykaring66.webp" width="600" alt="基础初始化设置 06"><img src="https://doc.mimy.cc/gykaring77.webp" width="600" alt="基础初始化设置 07"><img src="https://doc.mimy.cc/gykaring88.webp" width="600" alt="基础初始化设置 08"><img src="https://doc.mimy.cc/gykaring111.webp" width="600" alt="基础初始化设置 09"><img src="https://doc.mimy.cc/gykaring222.webp" width="600" alt="基础初始化设置 10"><img src="https://doc.mimy.cc/gykaring333.webp" width="600" alt="基础初始化设置 11"><img src="https://doc.mimy.cc/gykaring444.webp" width="600" alt="基础初始化设置 12"><img src="https://doc.mimy.cc/gykaring555.webp" width="600" alt="基础初始化设置 13"><img src="https://doc.mimy.cc/gykaring666.webp" width="600" alt="基础初始化设置 14"><h3 id="step-2-导入订阅地址" tabindex="-1">Step 2. 导入订阅地址 <a class="header-anchor" href="#step-2-导入订阅地址" aria-label="Permalink to &quot;Step 2. 导入订阅地址&quot;">​</a></h3><p>基础初始化完成后，您需要将账户的订阅链接导入到客户端中以获取服务器节点：</p><ol><li>登录<strong>fangqi官网</strong>，复制您的订阅地址</li><li>打开 Karing 客户端，在配置管理界面选择 <strong>从剪切板导入</strong>（软件会自动识别并粘贴您刚刚复制的链接）</li><li>在<strong>备注</strong>栏中输入：<code>速云</code></li><li>点击右上角的 <strong>✓（保存）</strong> 按钮</li></ol><img src="https://img.mimy.cc/sp222.webp" width="600" alt="Apple ID 授权配置图示"><img src="https://doc.mimy.cc/gykaring999.webp" width="600" alt="配置管理界面"><img src="https://img.mimy.cc/suyunka11.webp" width="600" alt="从剪切板导入示例"><h3 id="step-3-节点选择与延迟测试" tabindex="-1">Step 3. 节点选择与延迟测试 <a class="header-anchor" href="#step-3-节点选择与延迟测试" aria-label="Permalink to &quot;Step 3. 节点选择与延迟测试&quot;">​</a></h3><p>成功导入订阅后，建议在连接前进行一次网络延迟测试，以便选择最快、最稳定的节点：</p><ol><li>点击左上角的<strong>返回</strong>按钮回到主界面</li><li>点击屏幕最下方的 <strong>&gt;（进入）</strong> 符号，进入节点列表页</li><li>点击<strong>向下展开</strong>所有节点</li><li>点击<strong>闪电标志</strong>进行全局延迟测试</li><li>如果需要测试单个节点，可直接点击节点后面的<strong>三角形</strong>或<strong>数字标志</strong></li><li>在列表中，<strong>点击选中</strong>您想要使用的节点</li><li>可点击右上方齿轮图标把服务器排序打卡，节点可按照延迟排序</li></ol><div class="tip custom-block"><p class="custom-block-title">数值说明</p><p>数值越低，代表网络延迟越小，速度越快。</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ 三角提示</p><p>代表该节点当前连接错误，服务器可能不可用。</p></div><img src="https://doc.mimy.cc/xhykaring22.webp" width="600" alt="返回主界面"><img src="https://doc.mimy.cc/xhykaring33.webp" width="600" alt="进入节点列表"><img src="https://img.mimy.cc/suyunka22.webp" width="600" alt="节点向下展开与全局测试"><img src="https://doc.mimy.cc/xhykaring66.webp" width="600" alt="选择并确定目标节点"><h3 id="step-4-开启代理服务" tabindex="-1">Step 4. 开启代理服务 <a class="header-anchor" href="#step-4-开启代理服务" aria-label="Permalink to &quot;Step 4. 开启代理服务&quot;">​</a></h3><p>选择好满意的节点后，便可以一键开启系统代理服务：</p><ol><li>点击左上角<strong>返回</strong>回到主界面</li><li>点击屏幕正中下方的<strong>电源开关</strong>按钮</li><li>开启后，状态将由<strong>红色 ✕</strong> 变为<strong>绿色 ✓</strong>，下方也会同步显示您当前选中的节点名称。此时，您已成功连接网络</li></ol><img src="https://img.mimy.cc/suyunka33.webp" width="600" alt="开启服务并连通状态"><h3 id="step-5-日常维护-更新订阅" tabindex="-1">Step 5. 日常维护：更新订阅 <a class="header-anchor" href="#step-5-日常维护-更新订阅" aria-label="Permalink to &quot;Step 5. 日常维护：更新订阅&quot;">​</a></h3><p>当后续节点发生变动、或需要同步您的套餐剩余流量时，请按照以下步骤快速手动更新：</p><ol><li>在主界面点击进入<strong>我的配置</strong></li><li>找到您添加的配置，点击对应的<strong>云朵图标（更新）</strong>，即可同步官网最新的节点信息</li></ol><img src="https://img.mimy.cc/suyunka44.webp" width="600" alt="进入我的配置界面"><img src="https://img.mimy.cc/suyunka55.webp" width="600" alt="点击云朵图标更新订阅">',48)])])}const m=i(s,[["render",l]]);export{h as __pageData,m as default};
